package main

import (
	"fmt"
	"os"
)

func main() {
	var n int
	if _, err := fmt.Fscan(os.Stdin, &n); err != nil {
		fmt.Println("Enter an integer")
		return
	}
	if n < 0 {
		fmt.Println("Invalid")
	} else if n == 0 {
		fmt.Println("Empty")
	} else {
		fmt.Println("Pending")
	}
}
